<script setup>
import { computed } from 'vue';
import { Head, Link, useForm } from '@inertiajs/vue3';

const props = defineProps({ empresa: Object, pacote: Object, personalizado: Boolean });
const modoInicial = props.personalizado || new URLSearchParams(window.location.search).get('modo') === 'personalizado' ? 'personalizado' : 'pacote';
const form = useForm({ nome_contato: '', email: '', telefone: '', data_evento: '', convidados: props.pacote.min_convidados, tipo_local: 'interno', endereco_local: '', observacoes: '', aceita_contato: false, modo_cardapio: modoInicial, item_ids: [], item_quantidades: {} });
const moeda = (valor) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(Number(valor) || 0);
const itemSelecionado = (item) => form.item_ids.includes(item.id);
const quantidadeItem = (item) => Number(form.item_quantidades[item.id] || 1);
const totalBebidas = computed(() => (props.pacote.itens_livres || []).filter((item) => item.tipo_item === 'bebida' && itemSelecionado(item)).reduce((total, item) => total + quantidadeItem(item) * Number(item.preco_unitario || 0), 0));
const bebidasDisponiveis = computed(() => (props.pacote.itens_livres || []).filter((item) => item.tipo_item === 'bebida'));
const valorEstimado = computed(() => { const convidados = Number(form.convidados) || 0; const preco = Number(props.pacote.preco_base) || 0; const base = props.pacote.tipo_preco === 'por_pessoa' ? convidados * preco : preco; return moeda(base + totalBebidas.value); });
const alterarItem = (item, selecionado) => { form.item_ids = selecionado ? [...form.item_ids, item.id] : form.item_ids.filter((id) => id !== item.id); if (selecionado && item.tipo_item === 'bebida' && !form.item_quantidades[item.id]) form.item_quantidades[item.id] = 1; };
const atualizarQuantidade = (item, quantidade) => { form.item_quantidades[item.id] = Math.max(1, Number(quantidade) || 1); };
const ativarPersonalizado = () => { form.modo_cardapio = 'personalizado'; form.item_ids = []; form.item_quantidades = {}; };
const voltarParaPacote = () => { form.modo_cardapio = 'pacote'; form.item_ids = []; form.item_quantidades = {}; };
const enviar = () => { if (!form.aceita_contato) return; form.post(props.personalizado ? `/e/${props.empresa.slug}/cardapio-personalizado/solicitacoes` : `/e/${props.empresa.slug}/pacotes/${props.pacote.slug}/solicitacoes`); };
</script>

<template>
    <Head :title="`${personalizado ? 'Cardápio personalizado' : pacote.nome} · ${empresa.nome_fantasia}`" />
    <v-app>
        <v-main class="public-page">
            <v-container class="py-8 py-md-12" style="max-width: 1080px">
                <Link :href="`/e/${empresa.slug}`" class="back-link"><v-icon icon="mdi-arrow-left" size="18" /> Voltar ao cardápio</Link>
                <v-card class="mt-5" border flat rounded="xl" overflow="hidden">
                    <div class="package-hero pa-6 pa-md-10">
                        <div class="d-flex align-start ga-4"><v-avatar color="white" size="56"><v-icon icon="mdi-silverware-fork-knife" color="primary" size="30" /></v-avatar><div><div class="text-overline text-white opacity-80">{{ empresa.nome_fantasia }}</div><h1 class="text-h4 text-white font-weight-bold">{{ personalizado ? 'Cardápio personalizado' : pacote.nome }}</h1><div class="text-body-1 text-white opacity-80 mt-2">{{ personalizado ? 'Escolha os itens para criar uma proposta exclusiva para o seu evento.' : pacote.descricao || 'Monte a melhor experiência para o seu evento.' }}</div></div></div>
                        <div class="d-flex flex-wrap ga-3 mt-8"><v-chip v-if="!personalizado" color="white" variant="flat" prepend-icon="mdi-cash">R$ {{ pacote.preco_base }}{{ pacote.tipo_preco === 'por_pessoa' ? ' / pessoa' : ' / evento' }}</v-chip><v-chip v-if="!personalizado" color="white" variant="flat" prepend-icon="mdi-account-group-outline">{{ pacote.min_convidados }}{{ pacote.max_convidados ? `–${pacote.max_convidados}` : '+' }} convidados</v-chip><v-chip v-else color="white" variant="flat" prepend-icon="mdi-tune-variant">Valor a combinar</v-chip></div>
                    </div>
                    <v-card-text class="pa-6 pa-md-10">
                        <div class="d-flex align-center justify-space-between flex-wrap ga-3"><div><div class="text-h5 font-weight-bold">{{ form.modo_cardapio === 'personalizado' ? 'Monte seu cardápio' : 'O que está incluído' }}</div><div class="text-body-2 text-medium-emphasis mt-1 mb-6">{{ form.modo_cardapio === 'personalizado' ? 'Selecione os itens desejados e informe a quantidade das bebidas.' : 'Confira os pratos que fazem parte deste pacote.' }}</div></div><v-btn v-if="!personalizado && form.modo_cardapio === 'pacote'" color="primary" variant="tonal" prepend-icon="mdi-tune-variant" @click="ativarPersonalizado">Montar cardápio</v-btn><v-btn v-else-if="!personalizado" color="primary" variant="text" prepend-icon="mdi-arrow-left" @click="voltarParaPacote">Voltar ao pacote</v-btn></div>
                        <v-alert v-if="form.errors.item_ids" type="error" variant="tonal" class="mb-5">{{ form.errors.item_ids }}</v-alert>
                        <template v-if="form.modo_cardapio === 'pacote'"><v-row><v-col v-for="categoria in pacote.categorias" :key="categoria.id" cols="12" md="6"><v-card border flat rounded="lg"><v-card-item><template #prepend><v-avatar color="primary" variant="tonal" size="40"><v-icon icon="mdi-food-outline" /></v-avatar></template><v-card-title>{{ categoria.nome }}</v-card-title><v-card-subtitle>Itens incluídos no pacote</v-card-subtitle></v-card-item><v-divider /><v-list density="compact" class="py-2"><v-list-item v-for="item in categoria.itens" :key="item.id" :title="item.nome"><template #prepend><v-icon icon="mdi-check-circle" color="success" /></template></v-list-item></v-list></v-card></v-col></v-row><v-card v-if="bebidasDisponiveis.length" border flat rounded="lg" class="mt-5"><v-card-item><template #prepend><v-avatar color="primary" variant="tonal" size="40"><v-icon icon="mdi-glass-cocktail" /></v-avatar></template><v-card-title>Bebidas adicionais</v-card-title><v-card-subtitle>Escolha as bebidas e informe a quantidade desejada.</v-card-subtitle></v-card-item><v-divider /><v-list density="compact" class="py-2"><v-list-item v-for="item in bebidasDisponiveis" :key="item.id" :title="item.nome"><template #prepend><v-checkbox-btn :model-value="itemSelecionado(item)" color="primary" @update:model-value="alterarItem(item, $event)" /></template><template #subtitle><span v-if="item.referencia_consumo" class="text-caption text-medium-emphasis">{{ item.referencia_consumo }}</span></template><template #append><div class="d-flex align-center ga-2"><span class="text-caption text-medium-emphasis">{{ moeda(item.preco_unitario) }}/un.</span><v-text-field v-if="itemSelecionado(item)" :model-value="quantidadeItem(item)" type="number" min="1" density="compact" hide-details variant="outlined" class="drink-quantity" @update:model-value="atualizarQuantidade(item, $event)" /></div></template></v-list-item></v-list></v-card></template>
                        <v-card v-else border flat rounded="lg"><v-list density="compact" class="py-2"><v-list-item v-for="item in pacote.itens_livres" :key="item.id" :title="item.nome"><template #prepend><v-checkbox-btn :model-value="itemSelecionado(item)" color="primary" @update:model-value="alterarItem(item, $event)" /></template><template #subtitle><span v-if="item.tipo_item === 'bebida' && item.referencia_consumo" class="text-caption text-medium-emphasis">{{ item.referencia_consumo }}</span></template><template #append><div v-if="item.tipo_item === 'bebida'" class="d-flex align-center ga-2"><span class="text-caption text-medium-emphasis">{{ moeda(item.preco_unitario) }}/un.</span><v-text-field v-if="itemSelecionado(item)" :model-value="quantidadeItem(item)" type="number" min="1" density="compact" hide-details variant="outlined" class="drink-quantity" @update:model-value="atualizarQuantidade(item, $event)" /></div></template></v-list-item></v-list></v-card>
                        <v-divider class="my-8" /><div class="text-h6 font-weight-bold mb-4">Dados do evento</div><v-row><v-col cols="12" md="6"><v-text-field v-model="form.data_evento" label="Data do evento" type="date" :error-messages="form.errors.data_evento" /></v-col><v-col cols="12" md="6"><v-text-field v-model="form.convidados" label="Quantidade de convidados" type="number" :min="pacote.min_convidados" :max="pacote.max_convidados || undefined" :error-messages="form.errors.convidados" /></v-col><v-col cols="12" md="6"><v-select v-model="form.tipo_local" label="Local do evento" :items="[{ title: 'No estabelecimento', value: 'interno' }, { title: 'Em outro endereço', value: 'externo' }]" /></v-col><v-col v-if="form.tipo_local === 'externo'" cols="12" md="6"><v-text-field v-model="form.endereco_local" label="Endereço do evento" :error-messages="form.errors.endereco_local" /></v-col></v-row><div class="text-h6 font-weight-bold mt-4 mb-4">Seus dados</div><v-row><v-col cols="12" md="4"><v-text-field v-model="form.nome_contato" label="Nome completo" :error-messages="form.errors.nome_contato" /></v-col><v-col cols="12" md="4"><v-text-field v-model="form.telefone" label="WhatsApp / telefone" :error-messages="form.errors.telefone" /></v-col><v-col cols="12" md="4"><v-text-field v-model="form.email" label="E-mail" type="email" :error-messages="form.errors.email" /></v-col><v-col cols="12"><v-textarea v-model="form.observacoes" label="Observações" rows="3" :error-messages="form.errors.observacoes" /></v-col></v-row>
                        <v-card border flat rounded="lg" class="estimate-card mt-4"><v-card-text class="d-flex align-center justify-space-between flex-wrap ga-3"><div><div class="text-overline text-primary">Resumo antes de enviar</div><div class="text-body-2 text-medium-emphasis">{{ form.modo_cardapio === 'personalizado' ? 'Bebidas selecionadas somadas ao orçamento' : `Estimativa para ${form.convidados || 0} convidado(s)` }}</div></div><div class="text-h5 font-weight-bold text-primary">{{ form.modo_cardapio === 'personalizado' ? (totalBebidas > 0 ? moeda(totalBebidas) : 'A combinar') : valorEstimado }}</div></v-card-text></v-card>
                        <v-checkbox v-model="form.aceita_contato" color="primary" hide-details class="mt-3" label="Quero receber o contato da empresa para tirar dúvidas e obter mais informações." /><v-alert class="mt-2" type="info" variant="tonal" icon="mdi-information-outline">Marque a opção acima para autorizar o contato da empresa e liberar o envio da solicitação.</v-alert><v-btn block color="primary" size="large" rounded="lg" class="mt-5" prepend-icon="mdi-send-outline" :loading="form.processing" :disabled="!form.aceita_contato" @click="enviar">Enviar solicitação de orçamento</v-btn>
                    </v-card-text>
                </v-card>
            </v-container>
        </v-main>
    </v-app>
</template>

<style scoped>
.public-page { background: rgb(var(--v-theme-background)); min-height: 100vh; }
.back-link { display: inline-flex; align-items: center; gap: 6px; color: rgb(var(--v-theme-primary)); text-decoration: none; font-weight: 600; }
.package-hero { background: linear-gradient(135deg, #7f1d1d, #991b1b 55%, #b45309); padding: 24px 28px !important; }
.package-hero .mt-8 { margin-top: 16px !important; }
.estimate-card { background: rgba(var(--v-theme-primary), .06); border-color: rgba(var(--v-theme-primary), .18) !important; }
.drink-quantity { width: 76px; }
:deep(.v-list) { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); column-gap: 18px; }
@media (max-width: 600px) { :deep(.v-list) { grid-template-columns: 1fr; } }
</style>
